// Loop over input items and add a new field called 'myNewField' to the JSON of each one
function toDate(str){ //from dd/MM/yyyy hh:mm:ss
  const dateString = str;
  const [datePart, timePart] = dateString.split(' ');
  const [day, month, year] = datePart.split('/');
  const [hours, minutes,seconds] = timePart.split(':');

  // Note: Months are 0-indexed in JS (Jan = 0, Dec = 11)
  const dateObject = new Date(year, month - 1, day, hours, minutes,seconds);
  return dateObject
}
function getLink(str){

  //const re = new RegExp(/[(http(s)?):\/\/(www\.)?a-zA-Z0-9@:%._\+~#=]{2,256}\.[a-z]{2,6}\b([-a-zA-Z0-9@:%_\+.~#?&//=]*)/,"gi");
  //return re.exec(str)[0]
  return str.split("]")[0].split("[")[1].replace("\n"," ").replace("  "," ").replace(" ","%20")
}
/**
 * get number or PAC document record
 */
function getIdDocument(str){
  const re = new RegExp(/id_documento=(\d+)/,"ig");
  const res = re.exec(str)

  if (res){
    console.log(res)
    return "https://seia.sea.gob.cl/documentos/verDestinatarios.php?id_documento="+res[1]
  };

  return str
}
function docType(str){
  if (str.includes("inicio de PAC")){
    return "Solicitud PAC"
  }else if(str.includes("Observación") || str.includes("Observacion") ){
    return "observación"
  }
    else{
    return str.split(" ")[0].replace(":","").toLowerCase()
  }
}

for (const item of $input.all()) {
  const d = item.json.data;

  item.json.records = [];//init array

  const n_col = 8;

  for (let rowLoop = 0 ; rowLoop<=(item.json.data.length/n_col)-1;rowLoop++){
    const n_from = rowLoop*n_col;
    const link = getLink(d[n_from+3]);
    const title = d[n_from+3].split("[")[0].trim();

    const compose = {
      it:+d[n_from],
      register:d[n_from+1]?d[n_from+1]:null,
      dossier:d[n_from+2],
      document:{
        "title":title,
        "docType":docType(title),
        "link":link,
        "content":null,
        "contentType":link.includes("idDocumento")?"text":"file"
          },
      from:d[n_from+4],
      to:getIdDocument(d[n_from+5]),
      recordDate:toDate(d[n_from+6]),
    };
    //to Pac records
    item.json.records.push(compose)
  };
   delete item.json.data;
}

return $input.all();

// Loop over input items and add a new field called 'myNewField' to the JSON of each one
function contentCompose(arr){
  if(!arr){
    return null
  }

  const  sender = arr[0].split(":")[1].trim();

  const comment =arr
    .filter(row=> !row.startsWith("Nombre"))
    .filter(row=> !row.startsWith("Obs"))
    .filter(row=> !row.startsWith("Firmas"))
    .filter(row=> !row.endsWith("]"));

  return {sender,comment:comment.length>1?comment.join(" \n").trim():null}
}

for (const item of $input.all()) {
  item.json.document.content = contentCompose(item.json.document.content );
}

return $input.all();

for (const item of $input.all()) {
  const allRecords = item.json.records
  const allDates = allRecords.map(it=>it.recordDate);
  const stats = {
    firstRecord:allDates[0],
    lastRecord : allDates[allDates.length-1]
  }


  for (const it of allRecords){
    //key exist in stats
    if (!(it.document.docType in stats)){
      stats[it.document.docType] = 1;
    }else{
      stats[it.document.docType]+=1;
    } 
  }
  item.json.stats = stats;
}

return $input.all();

function getZone(valpo,ir){
  const zones = []
  if(valpo){zones.push(5)}
  if (ir){zones.push(14)}
  return zones
}

function getStatus(abandonado,aprobado,caducado,desistido,admision,calificacion,noAdmitido){
  const status = []
  if(abandonado){status.push(507)}
  if(aprobado){status.push(4)}
  if(caducado){status.push(1000)}
  if(desistido){status.push(8)}
  if(admision){status.push(2)}
  if(calificacion){status.push(3)}
  if(noAdmitido){status.push(6)}
  return status
}
