function genShortName(name){
  const sn = name.replace(/(\-|\_|\.|\:|\;|\(|#)/i,"")
    .replace(",","")
    .replace(")","")
    .replace("  "," ")
.replace(/(Almacenamiento|Generación|Sistema|Planta|Proyecto|Declaración|Impacto|Ambiental|Modificación|Ampliación|\sde|\scon|baterías|parque)/gi,"");

  const res = sn.trim()

return res[0].toUpperCase()+res.slice(1,res.length)
}
